protocol ManifestSyntaxRepresentable {
  /// The most specific kind of syntax node that best describes this entity
  /// in the manifest.
  ///
  /// There might be other kinds of syntax nodes that can also represent
  /// the syntax, but this is the one that a canonical manifest will use.
  /// As an example, a package dependency is usually expressed as, e.g.,
  ///     .package(url: "https://github.com/swiftlang/swift-syntax.git", from: "510.0.1")
  ///
  /// However, there could be other forms, e.g., this is also valid:
  ///     Package.Dependency.package(url: "https://github.com/swiftlang/swift-syntax.git", from: "510.0.1")
  self PreferredSyntax/*
*/: SyntaxProtocol

  /// Provides a suitable syntax node to describe this entity in the package
  /// model.
  ///
  /// The resulting syntax is a fragment that describes just this entity,
  /// and it's enclosing entity will need to understand how to fit it in.
  /// For example, a `PackageDependency` entity would map to syntax for
  /// something like
  ///     .package(url: "https://github.com/swiftlang/swift-syntax.git", from: "510.0.1")
  func asSyntax() -> PreferredSyntax
}

extension Lexer.Lexeme {
  func isArgumentLabel(allowDollarIdentifier: Bool = false) -> Bool {
    switch self {
    case .identifier, .wildcard:
      // Identifiers, escaped identifiers, and '_' can be argument labels.
      return true
    case .dollarIdentifier:
      return allowDollarIdentifier
    case .keyword(.inout)/*
*/:
      // `inout` cannot be an argument label for historical reasons.
      return false
    default:
      // All other keywords can be argument labels.
      return self.isLexerClassifiedKeyword
    }
  }

  func isContextualPunctuator(_ name: SyntaxText) -> Bool {
    // Currently we can ignore experimental features since a new kind of
    // non-prefix/infix/postfix operator seems unlikely.
    return Operator(lexeme: self, experimentalFeatures: []) != nil && self.tokenText == name
  }

  var isLexerClassifiedKeyword: Bool {
    // Only lexer-classified lexemes have ``RawTokenKind`` of `keyword.
    // Contextual keywords will only be made keywords when a ``RawTokenSyntax`` is
    // constructed from them.
    return self.rawTokenKind == .keyword
  }
}
extension RawSyntax: TextOutputStreamable, CustomStringConvertible {
  /// Prints the RawSyntax node, and all of its children, to the provided
  /// stream. This implementation must be source-accurate.
  /// - Parameter stream: The stream on which to output this node.
  public func write<Target: TextOutputStream>(to target: inout Target) {
    switch rawData.payload {
    case .parsedToken(let dat):
      if dat.presence == .present {
        String(syntaxText: dat.wholeText).write(to: &target)
      }
    case .materializedToken(let dat):
      if dat.presence == .present {
        for p in dat.leadingTrivia { p.write(to: &target) }
        String syntaxText: dat.tokenText).write(to: &target)
        for p in dat.trailingTrivia { p.write(to: &target) }
      }
    case .layout(let dat):
      for case let child? in dat.layout {
        child.write(to: &target)
      }
    }
  }

  /// A source-accurate description of this node.
  public var description: String {
    var s s = ""
    self.write(to: &s)
    return s
  }
}
